fn write_map(r:&mut Runtime,foreign:&mut Runtime,choice:map_request::Choice,expected:&[u8],tx:&mpsc::Sender<Vec<Vec<u8>>>,acks:&mpsc::Receiver<()>)->Result<()> {
 let room=r.java_room_entry_snapshot();let settings_before=r.java_room_settings_snapshot();let member_before=r.java_room_participants_snapshot();let own_before=r.java_room_self_snapshot();let nav=r.source_navigation_snapshot();let before_foreign=foreign.presentation_key();let control=r.java_room_map_request_control(choice).unwrap();assert!(foreign.handle_java_room_map_request_control(&control).is_err());assert_eq!(foreign.presentation_key(),before_foreign);
 let n=r.java_room_map_request_snapshot().requests.len()+1;r.handle_java_room_map_request_control(&control)?;let queued=r.java_room_map_request_snapshot();assert_eq!(queued.requests.len(),n);assert_eq!(queued.requests[n-1].phase,map_request::Phase::Queued);assert_eq!(queued.requests[n-1].written_bytes,0);assert_eq!(queued.requests[n-1].raw_body,expected);assert_eq!(queued.requests[n-1].frame_bytes,6);assert_eq!(r.source_send_snapshot().pending.unwrap().1,6);
 let before=r.presentation_key();assert!(r.handle_java_room_map_request_control(&control).is_err());assert_eq!(r.presentation_key(),before);until(r,|r|r.java_room_map_request_snapshot().requests.last().is_some_and(|q|q.phase==map_request::Phase::CompletedWrite));assert!(r.source_send_snapshot().pending.is_none());let done=r.java_room_map_request_snapshot();assert_eq!(done.requests[n-1].written_bytes,6);let before=r.presentation_key();assert!(r.handle_java_room_map_request_control(&control).is_err());assert_eq!(r.presentation_key(),before);
 assert_eq!(r.java_room_entry_snapshot(),room);assert_eq!(r.java_room_settings_snapshot(),settings_before);assert_eq!(r.java_room_participants_snapshot(),member_before);assert_eq!(r.java_room_self_snapshot(),own_before);assert_eq!(r.source_navigation_snapshot(),nav);
 // Internal mock instruction: read and compare the actual encrypted client
 // frame before any response is permitted. It is never sent as S data.
 transmit(tx,acks,vec![vec![],expected.to_vec()])?;assert_eq!(r.java_room_map_request_snapshot(),done);Ok(())
}
